56	/**
57	 * This class contains static utility methods that operate on or return objects of type {@link
58	 * Iterator}. Except as noted, each method has a corresponding {@link Iterable}-based method in the
59	 * {@link Iterables} class.
60	 *
61	 * <p><i>Performance notes:</i> Unless otherwise noted, all of the iterators produced in this class
62	 * are <i>lazy</i>, which means that they only advance the backing iteration when absolutely
63	 * necessary.
64	 *
65	 * <p>See the Guava User Guide section on <a href=
66	 * "https://github.com/google/guava/wiki/CollectionUtilitiesExplained#iterables">{@code
67	 * Iterators}</a>.
68	 *
69	 * @author Kevin Bourrillion
70	 * @author Jared Levy
71	 * @since 2.0
72	 */
73	@GwtCompatible
74	public final class Iterators {
75	  private Iterators() {}
76	
77	  /**
78	   * Returns the empty iterator.
79	   *
80	   * <p>The {@link Iterable} equivalent of this method is {@link ImmutableSet#of()}.
81	   */
82	  static <T extends @Nullable Object> UnmodifiableIterator<T> emptyIterator() {
83	    return emptyListIterator();
84	  }
85	
86	  /**
87	   * Returns the empty iterator.
88	   *
89	   * <p>The {@link Iterable} equivalent of this method is {@link ImmutableSet#of()}.
90	   */
91	  // Casting to any type is safe since there are no actual elements.
92	  @SuppressWarnings("unchecked")
93	  static <T extends @Nullable Object> UnmodifiableListIterator<T> emptyListIterator() {
94	    return (UnmodifiableListIterator<T>) ArrayItr.EMPTY;
95	  }
96	
97	  /**
98	   * This is an enum singleton rather than an anonymous class so ProGuard can figure out it's only
99	   * referenced by emptyModifiableIterator().
100	   */
101	  private enum EmptyModifiableIterator implements Iterator<Object> {
102	    INSTANCE;
103	
104	    @Override
105	    public boolean hasNext() {
106	      return false;
107	    }
108	
109	    @Override
110	    public Object next() {
111	      throw new NoSuchElementException();
112	    }
113	
114	    @Override
115	    public void remove() {
116	      checkRemove(false);
117	    }
118	  }
119	
120	  /**
121	   * Returns the empty {@code Iterator} that throws {@link IllegalStateException} instead of {@link
122	   * UnsupportedOperationException} on a call to {@link Iterator#remove()}.
123	   */
124	  // Casting to any type is safe since there are no actual elements.
125	  @SuppressWarnings("unchecked")
126	  static <T extends @Nullable Object> Iterator<T> emptyModifiableIterator() {
127	    return (Iterator<T>) EmptyModifiableIterator.INSTANCE;
128	  }
129	
130	  /** Returns an unmodifiable view of {@code iterator}. */
131	  public static <T extends @Nullable Object> UnmodifiableIterator<T> unmodifiableIterator(
132	      Iterator<? extends T> iterator) {
133	    checkNotNull(iterator);
134	    if (iterator instanceof UnmodifiableIterator) {
135	      @SuppressWarnings("unchecked") // Since it's unmodifiable, the covariant cast is safe
136	      UnmodifiableIterator<T> result = (UnmodifiableIterator<T>) iterator;
137	      return result;
138	    }
139	    return new UnmodifiableIterator<T>() {
140	      @Override
141	      public boolean hasNext() {
142	        return iterator.hasNext();
143	      }
144	
145	      @Override
146	      @ParametricNullness
147	      public T next() {
148	        return iterator.next();
149	      }
150	    };
151	  }
152	
153	  /**
154	   * Simply returns its argument.
155	   *
156	   * @deprecated no need to use this
157	   * @since 10.0
158	   */
159	  @InlineMe(
160	      replacement = "checkNotNull(iterator)",
161	      staticImports = "com.google.common.base.Preconditions.checkNotNull")
162	  @Deprecated
163	  public static <T extends @Nullable Object> UnmodifiableIterator<T> unmodifiableIterator(
164	      UnmodifiableIterator<T> iterator) {
165	    return checkNotNull(iterator);
166	  }
167	
168	  /**
169	   * Returns the number of elements remaining in {@code iterator}. The iterator will be left
170	   * exhausted: its {@code hasNext()} method will return {@code false}.
171	   */
172	  public static int size(Iterator<?> iterator) {
173	    long count = 0L;
174	    while (iterator.hasNext()) {
175	      iterator.next();
176	      count++;
177	    }
178	    return Ints.saturatedCast(count);
179	  }
180	
181	  /** Returns {@code true} if {@code iterator} contains {@code element}. */
182	  public static boolean contains(Iterator<?> iterator, @Nullable Object element) {
183	    if (element == null) {
184	      while (iterator.hasNext()) {
185	        if (iterator.next() == null) {
186	          return true;
187	        }
188	      }
189	    } else {
190	      while (iterator.hasNext()) {
191	        if (element.equals(iterator.next())) {
192	          return true;
193	        }
194	      }
195	    }
196	    return false;
197	  }
198	
199	  /**
200	   * Traverses an iterator and removes every element that belongs to the provided collection. The
201	   * iterator will be left exhausted: its {@code hasNext()} method will return {@code false}.
202	   *
203	   * @param removeFrom the iterator to (potentially) remove elements from
204	   * @param elementsToRemove the elements to remove
205	   * @return {@code true} if any element was removed from {@code iterator}
206	   */
207	  @CanIgnoreReturnValue
208	  public static boolean removeAll(Iterator<?> removeFrom, Collection<?> elementsToRemove) {
209	    checkNotNull(elementsToRemove);
210	    boolean result = false;
211	    while (removeFrom.hasNext()) {
212	      if (elementsToRemove.contains(removeFrom.next())) {
213	        removeFrom.remove();
214	        result = true;
215	      }
216	    }
217	    return result;
218	  }
219	
220	  /**
221	   * Removes every element that satisfies the provided predicate from the iterator. The iterator
222	   * will be left exhausted: its {@code hasNext()} method will return {@code false}.
223	   *
224	   * @param removeFrom the iterator to (potentially) remove elements from
225	   * @param predicate a predicate that determines whether an element should be removed
226	   * @return {@code true} if any elements were removed from the iterator
227	   * @since 2.0
228	   */
229	  @CanIgnoreReturnValue
230	  public static <T extends @Nullable Object> boolean removeIf(
231	      Iterator<T> removeFrom, Predicate<? super T> predicate) {
232	    checkNotNull(predicate);
233	    boolean modified = false;
234	    while (removeFrom.hasNext()) {
235	      if (predicate.apply(removeFrom.next())) {
236	        removeFrom.remove();
237	        modified = true;
238	      }
239	    }
240	    return modified;
241	  }
242	
243	  /**
244	   * Traverses an iterator and removes every element that does not belong to the provided
245	   * collection. The iterator will be left exhausted: its {@code hasNext()} method will return
246	   * {@code false}.
247	   *
248	   * @param removeFrom the iterator to (potentially) remove elements from
249	   * @param elementsToRetain the elements to retain
250	   * @return {@code true} if any element was removed from {@code iterator}
251	   */
252	  @CanIgnoreReturnValue
253	  public static boolean retainAll(Iterator<?> removeFrom, Collection<?> elementsToRetain) {
254	    checkNotNull(elementsToRetain);
255	    boolean result = false;
256	    while (removeFrom.hasNext()) {
257	      if (!elementsToRetain.contains(removeFrom.next())) {
258	        removeFrom.remove();
259	        result = true;
260	      }
261	    }
262	    return result;
263	  }
264	
265	  /**
266	   * Determines whether two iterators contain equal elements in the same order. More specifically,
267	   * this method returns {@code true} if {@code iterator1} and {@code iterator2} contain the same
268	   * number of elements and every element of {@code iterator1} is equal to the corresponding element
269	   * of {@code iterator2}.
270	   *
271	   * <p>Note that this will modify the supplied iterators, since they will have been advanced some
272	   * number of elements forward.
273	   */
274	  public static boolean elementsEqual(Iterator<?> iterator1, Iterator<?> iterator2) {
275	    while (iterator1.hasNext()) {
276	      if (!iterator2.hasNext()) {
277	        return false;
278	      }
279	      Object o1 = iterator1.next();
280	      Object o2 = iterator2.next();
281	      if (!Objects.equals(o1, o2)) {
282	        return false;
283	      }
284	    }
285	    return !iterator2.hasNext();
286	  }
287	
288	  /**
289	   * Returns a string representation of {@code iterator}, with the format {@code [e1, e2, ..., en]}.
290	   * The iterator will be left exhausted: its {@code hasNext()} method will return {@code false}.
291	   */
292	  public static String toString(Iterator<?> iterator) {
293	    StringBuilder sb = new StringBuilder().append('[');
294	    boolean first = true;
295	    while (iterator.hasNext()) {
296	      if (!first) {
297	        sb.append(", ");
298	      }
299	      first = false;
300	      sb.append(iterator.next());
301	    }
302	    return sb.append(']').toString();
303	  }
304	
305	  /**
306	   * Returns the single element contained in {@code iterator}.
307	   *
308	   * @throws NoSuchElementException if the iterator is empty
309	   * @throws IllegalArgumentException if the iterator contains multiple elements. The state of the
310	   *     iterator is unspecified.
311	   */
312	  @ParametricNullness
313	  public static <T extends @Nullable Object> T getOnlyElement(Iterator<T> iterator) {
314	    T first = iterator.next();
315	    if (!iterator.hasNext()) {
316	      return first;
317	    }
318	
319	    StringBuilder sb = new StringBuilder().append("expected one element but was: <").append(first);
320	    for (int i = 0; i < 4 && iterator.hasNext(); i++) {
321	      sb.append(", ").append(iterator.next());
322	    }
323	    if (iterator.hasNext()) {
324	      sb.append(", ...");
325	    }
326	    sb.append('>');
327	
328	    throw new IllegalArgumentException(sb.toString());
329	  }
330	
331	  /**
332	   * Returns the single element contained in {@code iterator}, or {@code defaultValue} if the
333	   * iterator is empty.
334	   *
335	   * @throws IllegalArgumentException if the iterator contains multiple elements. The state of the
336	   *     iterator is unspecified.
337	   */
338	  @ParametricNullness
339	  public static <T extends @Nullable Object> T getOnlyElement(
340	      Iterator<? extends T> iterator, @ParametricNullness T defaultValue) {
341	    return iterator.hasNext() ? getOnlyElement(iterator) : defaultValue;
342	  }
343	
344	  /**
345	   * Copies an iterator's elements into an array. The iterator will be left exhausted: its {@code
346	   * hasNext()} method will return {@code false}.
347	   *
348	   * @param iterator the iterator to copy
349	   * @param type the type of the elements
350	   * @return a newly-allocated array into which all the elements of the iterator have been copied
351	   */
352	  @GwtIncompatible // Array.newInstance(Class, int)
353	  public static <T extends @Nullable Object> T[] toArray(
354	      Iterator<? extends T> iterator, Class<@NonNull T> type) {
355	    List<T> list = newArrayList(iterator);
356	    return Iterables.<T>toArray(list, type);
357	  }
358	
359	  /**
360	   * Adds all elements in {@code iterator} to {@code collection}. The iterator will be left
361	   * exhausted: its {@code hasNext()} method will return {@code false}.
362	   *
363	   * @return {@code true} if {@code collection} was modified as a result of this operation
364	   */
365	  @CanIgnoreReturnValue
366	  public static <T extends @Nullable Object> boolean addAll(
367	      Collection<T> addTo, Iterator<? extends T> iterator) {
368	    checkNotNull(addTo);
369	    checkNotNull(iterator);
370	    boolean wasModified = false;
371	    while (iterator.hasNext()) {
372	      wasModified |= addTo.add(iterator.next());
373	    }
374	    return wasModified;
375	  }
376	
377	  /**
378	   * Returns the number of elements in the specified iterator that equal the specified object. The
379	   * iterator will be left exhausted: its {@code hasNext()} method will return {@code false}.
380	   *
381	   * @see Collections#frequency
382	   */
383	  public static int frequency(Iterator<?> iterator, @Nullable Object element) {
384	    int count = 0;
385	    while (contains(iterator, element)) {
386	      // Since it lives in the same class, we know contains gets to the element and then stops,
387	      // though that isn't currently publicly documented.
388	      count++;
389	    }
390	    return count;
391	  }
392	
393	  /**
394	   * Returns an iterator that cycles indefinitely over the elements of {@code iterable}.
395	   *
396	   * <p>The returned iterator supports {@code remove()} if the provided iterator does. After {@code
397	   * remove()} is called, subsequent cycles omit the removed element, which is no longer in {@code
398	   * iterable}. The iterator's {@code hasNext()} method returns {@code true} until {@code iterable}
399	   * is empty.
400	   *
401	   * <p><b>Warning:</b> Typical uses of the resulting iterator may produce an infinite loop. You
402	   * should use an explicit {@code break} or be certain that you will eventually remove all the
403	   * elements.
404	   */
405	  public static <T extends @Nullable Object> Iterator<T> cycle(Iterable<T> iterable) {
406	    checkNotNull(iterable);
407	    return new Iterator<T>() {
408	      Iterator<T> iterator = emptyModifiableIterator();
409	
410	      @Override
411	      public boolean hasNext() {
412	        /*
413	         * Don't store a new Iterator until we know the user can't remove() the last returned
414	         * element anymore. Otherwise, when we remove from the old iterator, we may be invalidating
415	         * the new one. The result is a ConcurrentModificationException or other bad behavior.
416	         *
417	         * (If we decide that we really, really hate allocating two Iterators per cycle instead of
418	         * one, we can optimistically store the new Iterator and then be willing to throw it out if
419	         * the user calls remove().)
420	         */
421	        return iterator.hasNext() || iterable.iterator().hasNext();
422	      }
423	
424	      @Override
425	      @ParametricNullness
426	      public T next() {
427	        if (!iterator.hasNext()) {
428	          iterator = iterable.iterator();
429	          if (!iterator.hasNext()) {
430	            throw new NoSuchElementException();
431	          }
432	        }
433	        return iterator.next();
434	      }
435	
436	      @Override
437	      public void remove() {
438	        iterator.remove();
439	      }
440	    };
441	  }
442	
443	  /**
444	   * Returns an iterator that cycles indefinitely over the provided elements.
445	   *
446	   * <p>The returned iterator supports {@code remove()}. After {@code remove()} is called,
447	   * subsequent cycles omit the removed element, but {@code elements} does not change. The
448	   * iterator's {@code hasNext()} method returns {@code true} until all of the original elements
449	   * have been removed.
450	   *
451	   * <p><b>Warning:</b> Typical uses of the resulting iterator may produce an infinite loop. You
452	   * should use an explicit {@code break} or be certain that you will eventually remove all the
453	   * elements.
454	   */
455	  @SafeVarargs
456	  public static <T extends @Nullable Object> Iterator<T> cycle(T... elements) {
457	    return cycle(newArrayList(elements));
458	  }
459	
460	  /**
461	   * Returns an Iterator that walks the specified array, nulling out elements behind it. This can
462	   * avoid memory leaks when an element is no longer necessary.
463	   *
464	   * <p>This method accepts an array with element type {@code @Nullable T}, but callers must pass an
465	   * array whose contents are initially non-null. The {@code @Nullable} annotation indicates that
466	   * this method will write nulls into the array during iteration.
467	   *
468	   * <p>This is mainly just to avoid the intermediate ArrayDeque in ConsumingQueueIterator.
469	   */
470	  private static <I extends Iterator<?>> Iterator<I> consumingForArray(@Nullable I... elements) {
471	    return new UnmodifiableIterator<I>() {
472	      int index = 0;
473	
474	      @Override
475	      public boolean hasNext() {
476	        return index < elements.length;
477	      }
478	
479	      @Override
480	      public I next() {
481	        if (!hasNext()) {
482	          throw new NoSuchElementException();
483	        }
484	        /*
485	         * requireNonNull is safe because our callers always pass non-null arguments. Each element
486	         * of the array becomes null only when we iterate past it and then clear it.
487	         */
488	        I result = requireNonNull(elements[index]);
489	        elements[index] = null;
490	        index++;
491	        return result;
492	      }
493	    };
494	  }
495	
496	  /**
497	   * Combines two iterators into a single iterator. The returned iterator iterates across the
498	   * elements in {@code a}, followed by the elements in {@code b}. The source iterators are not
499	   * polled until necessary.
500	   *
501	   * <p>The returned iterator supports {@code remove()} when the corresponding input iterator
502	   * supports it.
503	   */
504	  public static <T extends @Nullable Object> Iterator<T> concat(
505	      Iterator<? extends T> a, Iterator<? extends T> b) {
506	    checkNotNull(a);
507	    checkNotNull(b);
508	    return concat(consumingForArray(a, b));
509	  }
510	
511	  /**
512	   * Combines three iterators into a single iterator. The returned iterator iterates across the
513	   * elements in {@code a}, followed by the elements in {@code b}, followed by the elements in
514	   * {@code c}. The source iterators are not polled until necessary.
515	   *
516	   * <p>The returned iterator supports {@code remove()} when the corresponding input iterator
517	   * supports it.
518	   */
519	  public static <T extends @Nullable Object> Iterator<T> concat(
520	      Iterator<? extends T> a, Iterator<? extends T> b, Iterator<? extends T> c) {
521	    checkNotNull(a);
522	    checkNotNull(b);
523	    checkNotNull(c);
524	    return concat(consumingForArray(a, b, c));
525	  }
526	
527	  /**
528	   * Combines four iterators into a single iterator. The returned iterator iterates across the
529	   * elements in {@code a}, followed by the elements in {@code b}, followed by the elements in
530	   * {@code c}, followed by the elements in {@code d}. The source iterators are not polled until
531	   * necessary.
532	   *
533	   * <p>The returned iterator supports {@code remove()} when the corresponding input iterator
534	   * supports it.
535	   */
536	  public static <T extends @Nullable Object> Iterator<T> concat(
537	      Iterator<? extends T> a,
538	      Iterator<? extends T> b,
539	      Iterator<? extends T> c,
540	      Iterator<? extends T> d) {
541	    checkNotNull(a);
542	    checkNotNull(b);
543	    checkNotNull(c);
544	    checkNotNull(d);
545	    return concat(consumingForArray(a, b, c, d));
546	  }
547	
548	  /**
549	   * Combines multiple iterators into a single iterator. The returned iterator iterates across the
550	   * elements of each iterator in {@code inputs}. The input iterators are not polled until
551	   * necessary.
552	   *
553	   * <p>The returned iterator supports {@code remove()} when the corresponding input iterator
554	   * supports it.
555	   *
556	   * @throws NullPointerException if any of the provided iterators is null
557	   */
558	  @SafeVarargs
559	  public static <T extends @Nullable Object> Iterator<T> concat(Iterator<? extends T>... inputs) {
560	    return concatNoDefensiveCopy(Arrays.copyOf(inputs, inputs.length));
561	  }
562	
563	  /**
564	   * Combines multiple iterators into a single iterator. The returned iterator iterates across the
565	   * elements of each iterator in {@code inputs}. The input iterators are not polled until
566	   * necessary.
567	   *
568	   * <p>The returned iterator supports {@code remove()} when the corresponding input iterator
569	   * supports it. The methods of the returned iterator may throw {@code NullPointerException} if any
570	   * of the input iterators is null.
571	   */
572	  public static <T extends @Nullable Object> Iterator<T> concat(
573	      Iterator<? extends Iterator<? extends T>> inputs) {
574	    return new ConcatenatedIterator<>(inputs);
575	  }
576	
577	  /** Concats a varargs array of iterators without making a defensive copy of the array. */
578	  static <T extends @Nullable Object> Iterator<T> concatNoDefensiveCopy(
579	      Iterator<? extends T>... inputs) {
580	    for (Iterator<? extends T> input : checkNotNull(inputs)) {
581	      checkNotNull(input);
582	    }
583	    return concat(consumingForArray(inputs));
584	  }
585	
586	  /**
587	   * Divides an iterator into unmodifiable sublists of the given size (the final list may be
588	   * smaller). For example, partitioning an iterator containing {@code [a, b, c, d, e]} with a
589	   * partition size of 3 yields {@code [[a, b, c], [d, e]]} -- an outer iterator containing two
590	   * inner lists of three and two elements, all in the original order.
591	   *
592	   * <p>The returned lists implement {@link java.util.RandomAccess}.
593	   *
594	   * <p><b>Note:</b> The current implementation eagerly allocates storage for {@code size} elements.
595	   * As a consequence, passing values like {@code Integer.MAX_VALUE} can lead to {@link
596	   * OutOfMemoryError}.
597	   *
598	   * @param iterator the iterator to return a partitioned view of
599	   * @param size the desired size of each partition (the last may be smaller)
600	   * @return an iterator of immutable lists containing the elements of {@code iterator} divided into
601	   *     partitions
602	   * @throws IllegalArgumentException if {@code size} is nonpositive
603	   */
604	  public static <T extends @Nullable Object> UnmodifiableIterator<List<T>> partition(
605	      Iterator<T> iterator, int size) {
606	    return partitionImpl(iterator, size, false);
607	  }
608	
609	  /**
610	   * Divides an iterator into unmodifiable sublists of the given size, padding the final iterator
611	   * with null values if necessary. For example, partitioning an iterator containing {@code [a, b,
612	   * c, d, e]} with a partition size of 3 yields {@code [[a, b, c], [d, e, null]]} -- an outer
613	   * iterator containing two inner lists of three elements each, all in the original order.
614	   *
615	   * <p>The returned lists implement {@link java.util.RandomAccess}.
616	   *
617	   * @param iterator the iterator to return a partitioned view of
618	   * @param size the desired size of each partition
619	   * @return an iterator of immutable lists containing the elements of {@code iterator} divided into
620	   *     partitions (the final iterable may have trailing null elements)
621	   * @throws IllegalArgumentException if {@code size} is nonpositive
622	   */
623	  public static <T extends @Nullable Object>
624	      UnmodifiableIterator<List<@Nullable T>> paddedPartition(Iterator<T> iterator, int size) {
625	    return partitionImpl(iterator, size, true);
626	  }
627	
628	  private static <T extends @Nullable Object> UnmodifiableIterator<List<@Nullable T>> partitionImpl(
629	      Iterator<T> iterator, int size, boolean pad) {
630	    checkNotNull(iterator);
631	    checkArgument(size > 0);
632	    return new UnmodifiableIterator<List<@Nullable T>>() {
633	      @Override
634	      public boolean hasNext() {
635	        return iterator.hasNext();
636	      }
