644	        @Nullable T[] array = (@Nullable T[]) new Object[size];
645	        int count = 0;
646	        for (; count < size && iterator.hasNext(); count++) {
647	          array[count] = iterator.next();
648	        }
649	        for (int i = count; i < size; i++) {
650	          array[i] = null; // for GWT
651	        }
652	
653	        List<@Nullable T> list = unmodifiableList(asList(array));
654	        // TODO(b/192579700): Use a ternary once it no longer confuses our nullness checker.
655	        if (pad || count == size) {
656	          return list;
657	        } else {
