1307	  /**
1308	   * An iterator that performs a lazy N-way merge, calculating the next value each time the iterator
1309	   * is polled. This amortizes the sorting cost over the iteration and requires less memory than
1310	   * sorting all elements at once.
1311	   *
1312	   * <p>Retrieving a single element takes approximately O(log(M)) time, where M is the number of
1313	   * iterators. (Retrieving all elements takes approximately O(N*log(M)) time, where N is the total
1314	   * number of elements.)
1315	   */
1316	  private static final class MergingIterator<T extends @Nullable Object>
1317	      extends UnmodifiableIterator<T> {
1318	
1319	    // Wrapper class to track insertion order for stable sorting
1320	    private static class IndexedIterator<E extends @Nullable Object> {
1321	      final PeekingIterator<E> iterator;
1322	      final int index;
1323	
1324	      IndexedIterator(PeekingIterator<E> iterator, int index) {
1325	        this.iterator = iterator;
1326	        this.index = index;
1327	      }
1328	    }
1329	
1330	    final Queue<IndexedIterator<T>> queue;
1331	
1332	    MergingIterator(
1333	        Iterable<? extends Iterator<? extends T>> iterators, Comparator<? super T> itemComparator) {
1334	      // A comparator that's used by the heap, allowing the heap
1335	      // to be sorted based on the top of each iterator, with insertion order as tiebreaker
1336	      Comparator<IndexedIterator<T>> heapComparator =
1337	          (o1, o2) ->
1338	              ComparisonChain.start()
1339	                  .compare(o1.iterator.peek(), o2.iterator.peek(), itemComparator)
1340	                  // When elements are equal, use insertion order to maintain stability
1341	                  .compare(o1.index, o2.index)
1342	                  .result();
1343	
1344	      queue = new PriorityQueue<>(2, heapComparator);
1345	
1346	      int index = 0;
1347	      for (Iterator<? extends T> iterator : iterators) {
1348	        if (iterator.hasNext()) {
1349	          queue.add(new IndexedIterator<>(peekingIterator(iterator), index++));
1350	        }
1351	      }
1352	    }
1353	
1354	    @Override
1355	    public boolean hasNext() {
1356	      return !queue.isEmpty();
1357	    }
1358	
1359	    @Override
1360	    @ParametricNullness
1361	    public T next() {
1362	      IndexedIterator<T> nextIndexed = queue.remove();
1363	      PeekingIterator<T> nextIter = nextIndexed.iterator;
1364	      T next = nextIter.next();
1365	      if (nextIter.hasNext()) {
1366	        queue.add(nextIndexed);
1367	      }
1368	      return next;
1369	    }
1370	  }
