1372	  private static final class ConcatenatedIterator<T extends @Nullable Object>
1373	      implements Iterator<T> {
1374	    /* The last iterator to return an element.  Calls to remove() go to this iterator. */
1375	    private @Nullable Iterator<? extends T> toRemove;
1376	
1377	    /* The iterator currently returning elements. */
1378	    private Iterator<? extends T> iterator;
1379	
1380	    /*
1381	     * We track the "meta iterators," the iterators-of-iterators, below.  Usually, topMetaIterator
1382	     * is the only one in use, but if we encounter nested concatenations, we start a deque of
1383	     * meta-iterators rather than letting the nesting get arbitrarily deep.  This keeps each
1384	     * operation O(1).
1385	     */
1386	
1387	    private @Nullable Iterator<? extends Iterator<? extends T>> topMetaIterator;
1388	
1389	    // Only becomes nonnull if we encounter nested concatenations.
1390	    private @Nullable Deque<Iterator<? extends Iterator<? extends T>>> metaIterators;
1391	
1392	    ConcatenatedIterator(Iterator<? extends Iterator<? extends T>> metaIterator) {
1393	      iterator = emptyIterator();
1394	      topMetaIterator = checkNotNull(metaIterator);
1395	    }
1396	
1397	    // Returns a nonempty meta-iterator or, if all meta-iterators are empty, null.
1398	    private @Nullable Iterator<? extends Iterator<? extends T>> getTopMetaIterator() {
1399	      while (topMetaIterator == null || !topMetaIterator.hasNext()) {
1400	        if (metaIterators != null && !metaIterators.isEmpty()) {
1401	          topMetaIterator = metaIterators.removeFirst();
1402	        } else {
1403	          return null;
1404	        }
1405	      }
1406	      return topMetaIterator;
1407	    }
1408	
1409	    @Override
1410	    public boolean hasNext() {
1411	      while (!checkNotNull(iterator).hasNext()) {
1412	        // this weird checkNotNull positioning appears required by our tests, which expect
1413	        // both hasNext and next to throw NPE if an input iterator is null.
1414	
1415	        topMetaIterator = getTopMetaIterator();
1416	        if (topMetaIterator == null) {
1417	          return false;
1418	        }
1419	
1420	        iterator = topMetaIterator.next();
1421	
1422	        if (iterator instanceof ConcatenatedIterator) {
1423	          // Instead of taking linear time in the number of nested concatenations, unpack
1424	          // them into the queue
1425	          @SuppressWarnings("unchecked")
1426	          ConcatenatedIterator<T> topConcat = (ConcatenatedIterator<T>) iterator;
1427	          iterator = topConcat.iterator;
1428	
1429	          // topConcat.topMetaIterator, then topConcat.metaIterators, then this.topMetaIterator,
1430	          // then this.metaIterators
1431	
1432	          if (this.metaIterators == null) {
1433	            this.metaIterators = new ArrayDeque<>();
1434	          }
1435	          this.metaIterators.addFirst(this.topMetaIterator);
1436	          if (topConcat.metaIterators != null) {
1437	            while (!topConcat.metaIterators.isEmpty()) {
1438	              this.metaIterators.addFirst(topConcat.metaIterators.removeLast());
1439	            }
1440	          }
1441	          this.topMetaIterator = topConcat.topMetaIterator;
1442	        }
1443	      }
1444	      return true;
1445	    }
1446	
1447	    @Override
1448	    @ParametricNullness
1449	    public T next() {
1450	      if (hasNext()) {
1451	        toRemove = iterator;
1452	        return iterator.next();
1453	      } else {
1454	        throw new NoSuchElementException();
1455	      }
1456	    }
1457	
1458	    @Override
1459	    public void remove() {
1460	      if (toRemove == null) {
1461	        throw new IllegalStateException("no calls to next() since the last call to remove()");
1462	      }
1463	      toRemove.remove();
1464	      toRemove = null;
1465	    }
1466	  }
