353	    private static boolean isEmpty(Object value) {
354	      // Put types estimated to be the most frequent first.
355	      if (value instanceof CharSequence) {
356	        return ((CharSequence) value).length() == 0;
357	      } else if (value instanceof Collection) {
358	        return ((Collection<?>) value).isEmpty();
359	      } else if (value instanceof Map) {
360	        return ((Map<?, ?>) value).isEmpty();
361	      } else if (value instanceof java.util.Optional) {
362	        return !((java.util.Optional<?>) value).isPresent();
363	      } else if (value instanceof OptionalInt) {
364	        return !((OptionalInt) value).isPresent();
365	      } else if (value instanceof OptionalLong) {
366	        return !((OptionalLong) value).isPresent();
367	      } else if (value instanceof OptionalDouble) {
368	        return !((OptionalDouble) value).isPresent();
369	      } else if (value instanceof Optional) {
370	        return !((Optional<?>) value).isPresent();
371	      } else if (value.getClass().isArray()) {
372	        return Array.getLength(value) == 0;
373	      }
374	      return false;
375	    }
