395	        Object value = valueHolder.value;
396	        if (valueHolder instanceof UnconditionalValueHolder
397	            || (value == null
398	                ? !omitNullValuesSnapshot
399	                : (!omitEmptyValuesSnapshot || !isEmpty(value)))) {
400	          builder.append(nextSeparator);
401	          nextSeparator = ", ";
402	
403	          if (valueHolder.name != null) {
404	            builder.append(valueHolder.name).append('=');
405	          }
406	          if (value != null && value.getClass().isArray()) {
407	            Object[] objectArray = {value};
408	            String arrayString = Arrays.deepToString(objectArray);
409	            builder.append(arrayString, 1, arrayString.length() - 1);
410	          } else {
411	            builder.append(value);
412	          }
413	        }
414	      }
415	      return builder.append('}').toString();
416	    }
417	
418	    private ValueHolder addHolder() {
419	      ValueHolder valueHolder = new ValueHolder();
420	      holderTail = holderTail.next = valueHolder;
421	      return valueHolder;
422	    }
