445	    @CanIgnoreReturnValue
446	    private ToStringHelper addUnconditionalHolder(Object value) {
447	      UnconditionalValueHolder valueHolder = addUnconditionalHolder();
448	      valueHolder.value = value;
449	      return this;
450	    }
451	
452	    @CanIgnoreReturnValue
453	    private ToStringHelper addUnconditionalHolder(String name, Object value) {
454	      UnconditionalValueHolder valueHolder = addUnconditionalHolder();
455	      valueHolder.value = value;
456	      valueHolder.name = checkNotNull(name);
