487	  /**
488	   * Returns the greatest common divisor of {@code a, b}. Returns {@code 0} if {@code a == 0 && b ==
489	   * 0}.
490	   *
491	   * @throws IllegalArgumentException if {@code a < 0} or {@code b < 0}
492	   */
493	  public static long gcd(long a, long b) {
494	    /*
495	     * The reason we require both arguments to be >= 0 is because otherwise, what do you return on
496	     * gcd(0, Long.MIN_VALUE)? BigInteger.gcd would return positive 2^63, but positive 2^63 isn't an
497	     * int.
498	     */
499	    checkNonNegative("a", a);
500	    checkNonNegative("b", b);
501	    if (a == 0) {
502	      // 0 % b == 0, so b divides a, but the converse doesn't hold.
503	      // BigInteger.gcd is consistent with this decision.
504	      return b;
505	    } else if (b == 0) {
506	      return a; // similar logic
507	    }
508	    /*
509	     * Uses the binary GCD algorithm; see http://en.wikipedia.org/wiki/Binary_GCD_algorithm. This is
510	     * >60% faster than the Euclidean algorithm in benchmarks.
511	     */
512	    int aTwos = Long.numberOfTrailingZeros(a);
513	    a >>= aTwos; // divide out all 2s
514	    int bTwos = Long.numberOfTrailingZeros(b);
515	    b >>= bTwos; // divide out all 2s
516	    while (a != b) { // both a, b are odd
517	      // The key to the binary GCD algorithm is as follows:
518	      // Both a and b are odd. Assume a > b; then gcd(a - b, b) = gcd(a, b).
519	      // But in gcd(a - b, b), a - b is even and b is odd, so we can divide out powers of two.
520	
521	      // We bend over backwards to avoid branching, adapting a technique from
522	      // http://graphics.stanford.edu/~seander/bithacks.html#IntegerMinOrMax
523	
524	      long delta = a - b; // can't overflow, since a and b are nonnegative
525	
526	      long minDeltaOrZero = delta & (delta >> (Long.SIZE - 1));
527	      // equivalent to Math.min(delta, 0)
528	
529	      a = delta - minDeltaOrZero - minDeltaOrZero; // sets a to Math.abs(a - b)
530	      // a is now nonnegative and even
531	
532	      b += minDeltaOrZero; // sets b to min(old a, b)
533	      a >>= Long.numberOfTrailingZeros(a); // divide out all 2s, since 2 doesn't divide b
534	    }
535	    return a << min(aTwos, bTwos);
536	  }
