66	  /**
67	   * There are three methods to implement {@link FileChannel#transferTo(long, long,
68	   * WritableByteChannel)}:
69	   *
70	   * <ol>
71	   *   <li>Use sendfile(2) or equivalent. Requires that both the input channel and the output
72	   *       channel have their own file descriptors. Generally this only happens when both channels
73	   *       are files or sockets. This performs zero copies - the bytes never enter userspace.
74	   *   <li>Use mmap(2) or equivalent. Requires that either the input channel or the output channel
75	   *       have file descriptors. Bytes are copied from the file into a kernel buffer, then directly
76	   *       into the other buffer (userspace). Note that if the file is very large, a naive
77	   *       implementation will effectively put the whole file in memory. On many systems with paging
78	   *       and virtual memory, this is not a problem - because it is mapped read-only, the kernel
79	   *       can always page it to disk "for free". However, on systems where killing processes
80	   *       happens all the time in normal conditions (i.e., android) the OS must make a tradeoff
81	   *       between paging memory and killing other processes - so allocating a gigantic buffer and
82	   *       then sequentially accessing it could result in other processes dying. This is solvable
83	   *       via madvise(2), but that obviously doesn't exist in java.
84	   *   <li>Ordinary copy. Kernel copies bytes into a kernel buffer, from a kernel buffer into a
85	   *       userspace buffer (byte[] or ByteBuffer), then copies them from that buffer into the
86	   *       destination channel.
87	   * </ol>
88	   *
89	   * This value is intended to be large enough to make the overhead of system calls negligible,
90	   * without being so large that it causes problems for systems with atypical memory management if
91	   * approaches 2 or 3 are used.
92	   */
93	  private static final int ZERO_COPY_CHUNK_SIZE = 512 * 1024;
94	
95	  private ByteStreams() {}
96	
97	  /**
98	   * Copies all bytes from the input stream to the output stream. Does not close or flush either
99	   * stream.
100	   *
101	   * <p><b>Java 9 users and later:</b> this method should be treated as deprecated; use the
102	   * equivalent {@link InputStream#transferTo} method instead.
103	   *
104	   * @param from the input stream to read from
105	   * @param to the output stream to write to
106	   * @return the number of bytes copied
107	   * @throws IOException if an I/O error occurs
108	   */
109	  @CanIgnoreReturnValue
110	  public static long copy(InputStream from, OutputStream to) throws IOException {
111	    checkNotNull(from);
112	    checkNotNull(to);
113	    byte[] buf = createBuffer();
114	    long total = 0;
115	    while (true) {
116	      int r = from.read(buf);
117	      if (r == -1) {
118	        break;
119	      }
120	      to.write(buf, 0, r);
121	      total += r;
122	    }
123	    return total;
124	  }
125	
126	  /**
127	   * Copies all bytes from the readable channel to the writable channel. Does not close or flush
128	   * either channel.
129	   *
130	   * @param from the readable channel to read from
131	   * @param to the writable channel to write to
132	   * @return the number of bytes copied
133	   * @throws IOException if an I/O error occurs
134	   */
135	  @J2ktIncompatible
136	  @CanIgnoreReturnValue
137	  public static long copy(ReadableByteChannel from, WritableByteChannel to) throws IOException {
138	    checkNotNull(from);
139	    checkNotNull(to);
140	    if (from instanceof FileChannel) {
141	      FileChannel sourceChannel = (FileChannel) from;
142	      long oldPosition = sourceChannel.position();
143	      long position = oldPosition;
144	      long copied;
145	      do {
146	        copied = sourceChannel.transferTo(position, ZERO_COPY_CHUNK_SIZE, to);
147	        position += copied;
148	        sourceChannel.position(position);
149	      } while (copied > 0 || position < sourceChannel.size());
150	      return position - oldPosition;
151	    }
152	
153	    ByteBuffer buf = ByteBuffer.wrap(createBuffer());
154	    long total = 0;
155	    while (from.read(buf) != -1) {
156	      Java8Compatibility.flip(buf);
157	      while (buf.hasRemaining()) {
158	        total += to.write(buf);
159	      }
160	      Java8Compatibility.clear(buf);
161	    }
162	    return total;
163	  }
