44	/**
45	 * Static utility methods pertaining to {@link InetAddress} instances.
46	 *
47	 * <p><b>Important note:</b> Unlike {@code InetAddress.getByName()}, the methods of this class never
48	 * cause DNS services to be accessed. For this reason, you should prefer these methods as much as
49	 * possible over their JDK equivalents whenever you are expecting to handle only IP address string
50	 * literals -- there is no blocking DNS penalty for a malformed string.
51	 *
52	 * <p>When dealing with {@link Inet4Address} and {@link Inet6Address} objects as byte arrays (vis.
53	 * {@code InetAddress.getAddress()}) they are 4 and 16 bytes in length, respectively, and represent
54	 * the address in network byte order.
55	 *
56	 * <p>Examples of IP addresses and their byte representations:
57	 *
58	 * <dl>
59	 *   <dt>The IPv4 loopback address, {@code "127.0.0.1"}.
60	 *   <dd>{@code 7f 00 00 01}
61	 *   <dt>The IPv6 loopback address, {@code "::1"}.
62	 *   <dd>{@code 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 01}
63	 *   <dt>From the IPv6 reserved documentation prefix ({@code 2001:db8::/32}), {@code "2001:db8::1"}.
64	 *   <dd>{@code 20 01 0d b8 00 00 00 00 00 00 00 00 00 00 00 01}
65	 *   <dt>An IPv6 "IPv4 compatible" (or "compat") address, {@code "::192.168.0.1"}.
66	 *   <dd>{@code 00 00 00 00 00 00 00 00 00 00 00 00 c0 a8 00 01}
67	 *   <dt>An IPv6 "IPv4 mapped" address, {@code "::ffff:192.168.0.1"}.
68	 *   <dd>{@code 00 00 00 00 00 00 00 00 00 00 ff ff c0 a8 00 01}
69	 * </dl>
70	 *
71	 * <p>A few notes about IPv6 "IPv4 mapped" addresses and their observed use in Java.
72	 *
73	 * <p>"IPv4 mapped" addresses were originally a representation of IPv4 addresses for use on an IPv6
74	 * socket that could receive both IPv4 and IPv6 connections (by disabling the {@code IPV6_V6ONLY}
75	 * socket option on an IPv6 socket). Yes, it's confusing. Nevertheless, these "mapped" addresses
76	 * were never supposed to be seen on the wire. That assumption was dropped, some say mistakenly, in
77	 * later RFCs with the apparent aim of making IPv4-to-IPv6 transition simpler.
78	 *
79	 * <p>Technically one <i>can</i> create a 128bit IPv6 address with the wire format of a "mapped"
80	 * address, as shown above, and transmit it in an IPv6 packet header. However, Java's InetAddress
81	 * creation methods appear to adhere doggedly to the original intent of the "mapped" address: all
82	 * "mapped" addresses return {@link Inet4Address} objects.
83	 *
84	 * <p>For added safety, it is common for IPv6 network operators to filter all packets where either
85	 * the source or destination address appears to be a "compat" or "mapped" address. Filtering
86	 * suggestions usually recommend discarding any packets with source or destination addresses in the
87	 * invalid range {@code ::/3}, which includes both of these bizarre address formats. For more
88	 * information on "bogons", including lists of IPv6 bogon space, see:
89	 *
90	 * <ul>
91	 *   <li><a target="_parent"
92	 *       href="http://en.wikipedia.org/wiki/Bogon_filtering">http://en.wikipedia.
93	 *       org/wiki/Bogon_filtering</a>
94	 *   <li><a target="_parent"
95	 *       href="http://www.cymru.com/Bogons/ipv6.txt">http://www.cymru.com/Bogons/ ipv6.txt</a>
96	 *   <li><a target="_parent" href="http://www.cymru.com/Bogons/v6bogon.html">http://www.cymru.com/
97	 *       Bogons/v6bogon.html</a>
98	 *   <li><a target="_parent" href="http://www.space.net/~gert/RIPE/ipv6-filters.html">http://www.
99	 *       space.net/~gert/RIPE/ipv6-filters.html</a>
100	 * </ul>
101	 *
102	 * @author Erik Kline
103	 * @since 5.0
104	 */
105	@J2ktIncompatible
106	@GwtIncompatible
107	public final class InetAddresses {
108	  private static final int IPV4_PART_COUNT = 4;
109	  private static final int IPV6_PART_COUNT = 8;
110	  private static final char IPV4_DELIMITER = '.';
111	  private static final char IPV6_DELIMITER = ':';
112	  private static final CharMatcher IPV4_DELIMITER_MATCHER = CharMatcher.is(IPV4_DELIMITER);
113	  private static final CharMatcher IPV6_DELIMITER_MATCHER = CharMatcher.is(IPV6_DELIMITER);
114	  private static final Inet4Address LOOPBACK4 = (Inet4Address) forString("127.0.0.1");
115	  private static final Inet4Address ANY4 = (Inet4Address) forString("0.0.0.0");
116	
117	  private InetAddresses() {}
118	
119	  /**
120	   * Returns an {@link Inet4Address}, given a byte array representation of the IPv4 address.
121	   *
122	   * @param bytes byte array representing an IPv4 address (should be of length 4)
123	   * @return {@link Inet4Address} corresponding to the supplied byte array
124	   * @throws IllegalArgumentException if a valid {@link Inet4Address} can not be created
125	   */
126	  private static Inet4Address getInet4Address(byte[] bytes) {
127	    checkArgument(
128	        bytes.length == 4,
129	        "Byte array has invalid length for an IPv4 address: %s != 4.",
130	        bytes.length);
131	
132	    // Given a 4-byte array, this cast should always succeed.
133	    return (Inet4Address) bytesToInetAddress(bytes, null);
134	  }
135	
136	  /**
137	   * Returns the {@link InetAddress} having the given string representation.
138	   *
139	   * <p>This deliberately avoids all nameservice lookups (e.g. no DNS).
140	   *
141	   * <p>IPv4-mapped IPv6 addresses (e.g. {@code "::ffff:192.168.0.1"}) are returned as {@link
142	   * Inet4Address} objects, not {@link Inet6Address}. This is consistent with the behavior of {@link
143	   * InetAddress}.
144	   *
145	   * <p>This method accepts non-ASCII digits, for example {@code "１９２.１６８.０.１"} (those are fullwidth
146	   * characters). That is consistent with {@link InetAddress}, but not with various RFCs. If you
147	   * want to accept ASCII digits only, you can use something like {@code
148	   * CharMatcher.ascii().matchesAllOf(ipString)}.
149	   *
150	   * <p>The scope ID is validated against the interfaces on the machine, which requires permissions
151	   * under Android.
152	   *
153	   * <p><b>Android users on API >= 29:</b> Prefer {@code InetAddresses.parseNumericAddress}.
