74	  private static final class PerThreadQueuedDispatcher extends Dispatcher {
75	
76	    // This dispatcher matches the original dispatch behavior of EventBus.
77	
78	    /** Per-thread queue of events to dispatch. */
79	    @SuppressWarnings("ThreadLocalUsage") // Each Dispatcher needs its own state.
80	    private final ThreadLocal<Queue<Event>> queue =
81	        new ThreadLocal<Queue<Event>>() {
82	          @Override
83	          protected Queue<Event> initialValue() {
84	            return new ArrayDeque<>();
85	          }
86	        };
