88	    /** Per-thread dispatch state, used to avoid reentrant event dispatching. */
89	    @SuppressWarnings("ThreadLocalUsage") // Each Dispatcher needs its own state.
90	    private final ThreadLocal<Boolean> dispatching =
91	        new ThreadLocal<Boolean>() {
92	          @Override
93	          protected Boolean initialValue() {
94	            return false;
95	          }
96	        };
