98	    @Override
99	    void dispatch(Object event, Iterator<Subscriber> subscribers) {
100	      checkNotNull(event);
101	      checkNotNull(subscribers);
102	      // requireNonNull accommodates Android's @RecentlyNullable annotation on ThreadLocal.get
103	      Queue<Event> queueForThread = requireNonNull(queue.get());
104	      queueForThread.offer(new Event(event, subscribers));
105	
106	      if (!dispatching.get()) {
107	        dispatching.set(true);
108	        try {
109	          Event nextEvent;
110	          while ((nextEvent = queueForThread.poll()) != null) {
111	            while (nextEvent.subscribers.hasNext()) {
112	              nextEvent.subscribers.next().dispatchEvent(nextEvent.event);
113	            }
114	          }
115	        } finally {
116	          dispatching.remove();
117	          queue.remove();
118	        }
119	      }
120	    }
