133	  /** Implementation of a {@link #legacyAsync()} dispatcher. */
134	  private static final class LegacyAsyncDispatcher extends Dispatcher {
135	
136	    // This dispatcher matches the original dispatch behavior of AsyncEventBus.
137	    //
138	    // We can't really make any guarantees about the overall dispatch order for this dispatcher in
139	    // a multithreaded environment for a couple of reasons:
140	    //
141	    // 1. Subscribers to events posted on different threads can be interleaved with each other
142	    //    freely. (A event on one thread, B event on another could yield any of
143	    //    [a1, a2, a3, b1, b2], [a1, b2, a2, a3, b2], [a1, b2, b3, a2, a3], etc.)
144	    // 2. It's possible for subscribers to actually be dispatched to in a different order than they
145	    //    were added to the queue. It's easily possible for one thread to take the head of the
146	    //    queue, immediately followed by another thread taking the next element in the queue. That
147	    //    second thread can then dispatch to the subscriber it took before the first thread does.
148	    //
149	    // All this makes me really wonder if there's any value in queueing here at all. A dispatcher
150	    // that simply loops through the subscribers and dispatches the event to each would actually
151	    // probably provide a stronger order guarantee, though that order would obviously be different
152	    // in some cases.
153	
154	    /** Global event queue. */
155	    private final ConcurrentLinkedQueue<EventWithSubscriber> queue = new ConcurrentLinkedQueue<>();
156	
157	    @Override
158	    void dispatch(Object event, Iterator<Subscriber> subscribers) {
159	      checkNotNull(event);
160	      while (subscribers.hasNext()) {
161	        queue.add(new EventWithSubscriber(event, subscribers.next()));
162	      }
163	
164	      EventWithSubscriber e;
165	      while ((e = queue.poll()) != null) {
166	        e.subscriber.dispatchEvent(e.event);
167	      }
168	    }
169	
170	    private static final class EventWithSubscriber {
171	      private final Object event;
172	      private final Subscriber subscriber;
173	
174	      private EventWithSubscriber(Object event, Subscriber subscriber) {
175	        this.event = event;
176	        this.subscriber = subscriber;
177	      }
178	    }
179	  }
180	
181	  /** Implementation of {@link #immediate()}. */
182	  private static final class ImmediateDispatcher extends Dispatcher {
183	    private static final ImmediateDispatcher INSTANCE = new ImmediateDispatcher();
184	
185	    @Override
186	    void dispatch(Object event, Iterator<Subscriber> subscribers) {
187	      checkNotNull(event);
188	      while (subscribers.hasNext()) {
189	        subscribers.next().dispatchEvent(event);
190	      }
191	    }
192	  }
193	}
