78	     * and will cause {@link #build} to fail.
79	     */
80	    @CanIgnoreReturnValue
81	    public <T extends B> Builder<B> put(TypeToken<T> key, T value) {
82	      mapBuilder.put(key.rejectTypeVariables(), value);
83	      return this;
84	    }
